use strict;
use warnings;
my ($input, $output) = @ARGV;
die "usage: $0 input.lua output.md\n" unless $input && $output;

# Derive title from input filename: lua_aaaseed_draw.lua -> "Draw",
# lua_aaaseed_GABU_OBJ.lua -> "GABU_OBJ" (uppercase preserved when basename has uppercase letters).
my $title;
{
    my $base = $input;
    $base =~ s|.*/||;
    $base =~ s/\.lua$//i;
    $base =~ s/^lua_aaaseed_//i;
    if ($base =~ /[A-Z]/) {
        $title = $base;
    } else {
        $title = ucfirst(lc($base));
    }
}

open(my $fh, '<', $input) or die "open $input: $!";
my @lines = <$fh>;
close $fh;

sub parse_header {
    my $line = shift;
    if ($line =~ /^--\s*(#+)\s+(.+?)\s*$/) {
        return (length($1), $2);
    }
    return ();
}

my @sections;
my $current = { level => 0, title => "_PREAMBLE_", prose => [], code => [] };
push @sections, $current;
my $banner_consumed = 0;

for my $line (@lines) {
    chomp(my $stripped = $line);
    my ($lvl, $thd) = parse_header($line);
    if ($lvl) {
        $current = { level => $lvl, title => $thd, prose => [], code => [] };
        push @sections, $current;
        $banner_consumed = 1;
        next;
    }
    if ($banner_consumed && $stripped =~ /^--\s*$/) {
        $banner_consumed = 0;
        next;
    }
    $banner_consumed = 0;

    if ($stripped =~ /^\s+\S.*\(/) {
        push @{$current->{code}}, $stripped;
        next;
    }
    if ($stripped =~ /^\s*--/) {
        if (@{$current->{code}} == 0) {
            my $p = $stripped;
            $p =~ s/^\s*--\s*//;
            $p =~ s/\s+$//;
            push @{$current->{prose}}, $p;
        } else {
            push @{$current->{code}}, $stripped;
        }
        next;
    }
    if ($stripped =~ /^\s*$/) {
        push @{$current->{code}}, "" if @{$current->{code}};
        next;
    }
    push @{$current->{code}}, $stripped;
}

# Scientific numbering
my @counters = (0) x 8;
for my $s (@sections) {
    next if $s->{level} == 0;
    my $L = $s->{level};
    $counters[$L]++;
    for my $i ($L+1 .. $#counters) { $counters[$i] = 0; }
    my @parts = @counters[1..$L];
    $s->{number} = join(".", @parts) . ".";
}

sub render_prose {
    my ($out_fh, $prose) = @_;
    return unless @$prose;
    my @p = @$prose;
    while (@p && $p[0] eq '') { shift @p; }
    while (@p && $p[-1] eq '') { pop @p; }
    return unless @p;

    my @paragraph;
    my $flush = sub {
        return unless @paragraph;
        for my $i (0 .. $#paragraph) {
            if ($i < $#paragraph) {
                print $out_fh $paragraph[$i] . "  \n";
            } else {
                print $out_fh $paragraph[$i] . "\n";
            }
        }
        print $out_fh "\n";
        @paragraph = ();
    };
    for my $line (@p) {
        if ($line eq '') { $flush->(); }
        else { push @paragraph, $line; }
    }
    $flush->();
}

sub make_anchor {
    my ($number, $tit) = @_;
    my $base = ($number // "") . " " . $tit;
    $base = lc($base);
    $base =~ s/[^a-z0-9 -]//g;
    $base =~ s/\s+/-/g;
    $base =~ s/-+/-/g;
    $base =~ s/^-+|-+$//g;
    return $base;
}

open(my $out, '>', $output) or die "write $output: $!";
print $out "# AAASeed Lua API -- $title\n\n";
my $src = $input; $src =~ s|.*/||;
print $out "Generated from `$src`. Do not edit this file directly -- edit the .lua source.\n\n";

print $out "## Table of contents\n\n";
for my $s (@sections) {
    next if $s->{level} == 0;
    my $anchor = make_anchor($s->{number}, $s->{title});
    my $indent = "  " x ($s->{level} - 1);
    print $out "$indent- [$s->{number} $s->{title}](#$anchor)\n";
}
print $out "\n---\n\n";

for my $s (@sections) {
    next if $s->{level} == 0 && (@{$s->{prose}} == 0 && @{$s->{code}} == 0);
    if ($s->{level} > 0) {
        my $h = "#" x ($s->{level} + 1);
        print $out "$h $s->{number} $s->{title}\n\n";
    }
    render_prose($out, $s->{prose});
    if (@{$s->{code}}) {
        my @code = @{$s->{code}};
        while (@code && $code[0] =~ /^\s*$/) { shift @code; }
        while (@code && $code[-1] =~ /^\s*$/) { pop @code; }
        if (@code) {
            print $out "```lua\n";
            print $out "$_\n" for @code;
            print $out "```\n\n";
        }
    }
}
close $out;

my $sec_count = scalar grep { $_->{level} > 0 } @sections;
print STDERR "Wrote $output ($sec_count sections, title='$title')\n";
